import {roomGallery,roomToolbar,roomMatrix,roomNames} from './photo-comparison-view.js';

const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>v!==null&&v!==undefined&&Number.isFinite(Number(v));
const fmt=(v,d=0)=>num(v)?Number(v).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}):'Unavailable';
const usd=(v,d=0)=>num(v)?'$'+fmt(v,d):'Unavailable';
const pct=(v,sign=true)=>num(v)?(sign&&v>=0?'+':'')+fmt(v*100,1)+'%':'Unavailable';
const dollars=v=>num(v)?(v>=0?'+':'−')+usd(Math.abs(v)):'Unavailable';
const pp=v=>num(v)?(v>=0?'+':'')+fmt(v,1)+' pp':'Unavailable';
const chapters=[['answer','The answer'],['drivers','Why some earn more'],['question','Cabin proof'],['revenue','Property comparisons'],['amenities','Price, not nights'],['markets','Where it works'],['implications','Limits & next steps'],['explorer','All candidates'],['sources','Research files']];
const NAV=['answer','drivers','question','revenue','markets','implications'];
const CONF='Confirmed Adult-Themed';
let E,P,D=null,REV={},rows,market='all',sort='premium',activeMarket='Blue Ridge, GA',chapter='question',presenting=false,profile=null,viewer=null;
let explorer={query:'',classification:'all',market:'all'};
const labels={hot_tub:'Hot tub',sauna:'Sauna',pool:'Pool access',game_room:'Game room',fire_pit:'Fire pit',movie_theater:'Theater',waterfront:'Waterfront',lake_access:'Lake access',outdoor_dining:'Outdoor dining'};
const badges=a=>`<div class="amenity-badges">${Object.entries(labels).filter(([k])=>a?.[k]===1).map(([,v])=>`<span class="amenity-pill present">✓ ${v}</span>`).join('')||'<span class="amenity-empty">No present amenity flags recorded; other advertised features may not be captured.</span>'}</div>`;
const btn=(id,label='Explore property & comps ↗')=>`<button class="mini-link" data-open="${id}">${label}</button>`;
const k$=v=>num(v)?'$'+fmt(v/1000)+'K':'';
const revOf=id=>REV[String(id)];
const inner=(id,kicker,title,body,alt=false)=>`<section id="${id}" class="chapter ${alt?'alt':''}" data-chapter><div class="chapter-inner"><span class="eyebrow">${kicker}</span><h2>${title}</h2>${body}</div></section>`;
const fitBadge=p=>p.comparability?`<span class="fit-badge fit-${p.comparability.rating.toLowerCase()}">Comparability: ${esc(p.comparability.rating)}</span>`:'';
function resolutionPanel(p){const r=p.resolution_review;if(!r)return '';return `<div class="fit-resolution" data-fit-resolution="${p.id}"><p><strong>Evidence established:</strong> ${esc(r.resolved)}</p><p><strong>Remaining differences:</strong> ${esc(r.remaining)}</p><p class="chart-note">Public review ${esc(r.review_date)}. ${r.sources.map((url,i)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">Evidence ${i+1} ↗</a>`).join(' · ')}. A completed review does not mean the properties are equivalent.</p></div>`;}
function marketShortlist(){const a=E.acquisition;return `<div class="acquisition-shortlist" id="acquisition-shortlist"><span class="overline">WHERE TO SCREEN FIRST</span><div class="shortlist-grid">${a.market_shortlist.slice(0,3).map(m=>`<article class="focused-card"><span class="overline">${esc(m.screening_priority)}</span><h4>${esc(m.market)}</h4><b class="focused-premium">${pct(m.median_pct_gap)}</b><p>${m.confirmed_properties} confirmed properties · ${m.above_median} above their selected median</p><p>${esc(m.interpretation)}</p></article>`).join('')}</div><p class="chart-note">Pigeon Forge, Gatlinburg and Banner Elk each contain one confirmed example; keep them as supporting observations. ${esc(a.scope)} No verified examples in the other studied markets does not establish failure.</p></div>`;}
function acquisitionBuybox(){const a=E.acquisition;return `<div class="acquisition-buybox" id="acquisition-buybox"><span class="overline">A PRACTICAL PROPERTY SCREEN</span><h3>A couples cabin first.<br>A differentiated adult experience.</h3><dl class="fit-factors">${a.buybox.slice(0,4).map(x=>`<div><dt>${esc(x.feature)}</dt><dd>${esc(x.screen)}</dd></div>`).join('')}</dl><p class="simple-caution">${esc(a.not_established)} Evaluate each acquisition against equally competitive conventional properties; the sample median is not an automatic underwriting uplift.</p><details class="optional-detail"><summary>Actual modeled revenue benchmarks — not a forecast</summary><div class="table-scroll"><table class="data-table"><thead><tr><th>Example</th><th>Adult Revenue Potential</th><th>Selected conventional median</th><th>Comps / fit</th></tr></thead><tbody>${a.benchmarks.map(p=>`<tr><td>${btn(p.listing_id,esc(p.title))}<small>${esc(p.market)}</small></td><td>${usd(p.adult_revenue_potential)}</td><td>${usd(p.conventional_median_revenue_potential)}</td><td>${p.comp_count} / ${esc(p.comparability)}</td></tr>`).join('')}</tbody></table></div><p class="chart-note">These are specific observed modeled estimates, not a revenue target or transferable purchase forecast. Inspect each property's room, amenity and layout differences.</p></details></div>`;}
function reliabilityLine(p){const r=p.reliability;if(!r)return '';return `<div class="property-reliability" data-reliability-property="${p.id}"><strong>Comp-selection sensitivity</strong><p>${r.loo_testable?`Omitting one selected comp at a time gives ${pct(r.loo_min_pct_gap)} to ${pct(r.loo_max_pct_gap)}. ${esc(r.direction_status)}.`:'One selected comp: removing it leaves no benchmark, so omission stability cannot be tested.'}</p><p class="chart-note">${r.shared_selected_comps} of ${r.selected_comp_count} selected controls are reused by other confirmed properties. ${r.optional_tests?`${r.optional_tests} individually added reviewed alternatives; ${r.optional_direction_changes} direction changes.`:'No reviewed optional additions available.'} Sensitivity range, not a confidence interval. The selected benchmark is unchanged.</p></div>`;}
function reliabilitySummary(){const r=E.reliability,s=r.summary,operator=r.aggregate_tests.find(a=>a.test.startsWith('Exclude recorded repeated operator'));return `<div class="reliability-findings" id="reliability-findings"><span class="overline">DOES THE DIRECTION HOLD?</span><h3>Direction holds.<br>The size is less certain.</h3><p>${s.positive_all_omissions} positive and ${s.negative_all_omissions} negative properties keep their direction under every single-comp omission. ${s.testable_properties} are testable; the single-comp Banner Elk observation is not.</p><p>${s.magnitude_sensitive_properties} omission ranges span at least 20 percentage points. Omitting one adult property at a time leaves the sample median between <strong>${pct(s.adult_omission_min_pct_gap)} and ${pct(s.adult_omission_max_pct_gap)}</strong>.</p><p>${s.shared_control_ids} conventional IDs are reused across ${s.exposed_properties} adult properties. Removing one shared control from every set leaves sample medians between ${pct(s.shared_omission_min_pct_gap)} and ${pct(s.shared_omission_max_pct_gap)}. ${operator?`Excluding the three properties carrying the repeated Your Spicy Stay evidence label leaves ${operator.properties} properties and a ${pct(operator.median_pct_gap)} median.`:''} Other operator links remain unverified.</p><p class="chart-note">These checks do not establish equal layouts, area or quality. No comp is removed from the selected benchmark. Ranges are descriptive, not confidence intervals.</p><details class="optional-detail"><summary>Inspect all 15 property sensitivity ranges</summary><div class="table-scroll"><table class="data-table"><thead><tr><th>Property</th><th>Comps</th><th>Selected gap</th><th>Omit-one-comp range</th><th>Comparability</th></tr></thead><tbody>${r.properties.map(p=>`<tr><td>${btn(p.adult_id,esc(p.title))}<small>${usd(revOf(p.adult_id))} modeled revenue</small></td><td>${p.selected_comp_count}</td><td>${pct(p.baseline_pct_gap)}</td><td>${p.loo_testable?`${pct(p.loo_min_pct_gap)} to ${pct(p.loo_max_pct_gap)}`:'Untestable: one comp'}</td><td>${esc(p.comparability)}</td></tr>`).join('')}</tbody></table></div><p class="chart-note">The workbook includes every omission and optional-addition scenario, shared-control tests, exact configuration restrictions and operator evidence. The 20-point span flag is descriptive, not a significance threshold.</p></details></div>`;}
function fitPanel(p){const a=p.comparability;if(!a)return '';return `<div class="fit-panel" data-fit-assessment="${p.id}">${fitBadge(p)}<p>${esc(a.selection_reason)}</p><p class="chart-note">Relative fit assessment; ${esc(a.statistical_confidence)} Strong does not mean a proven theme premium.</p><details class="optional-detail"><summary>Sleeping layout, rooms, amenities & location</summary>${resolutionPanel(p)}<dl class="fit-factors">${[['Sleeping layout',a.sleeping_layout],['Bathroom quality & count',a.bathrooms],['Kitchen & interiors',a.kitchen_and_interiors],['Hot tub / sauna / other amenities',a.spa_amenities],['Photo coverage',a.photo_coverage],['Views, privacy & location',a.views_privacy_location]].map(([label,note])=>`<div><dt>${esc(label)}</dt><dd>${esc(note)}</dd></div>`).join('')}</dl><p class="chart-note">${esc(a.evidence_basis)} <a href="${esc(a.source_url)}" target="_blank" rel="noopener noreferrer">Public listing ↗</a>. Exact conventional room photographs and source listing links are in Compare comps.</p></details></div>`;}

async function init(){
  const results=await Promise.all(['data/leadership-report.json','data/photo-comparisons.json'].map(async url=>{const r=await fetch(url);if(!r.ok)throw Error('Research data could not be loaded');return r.json();}));
  [E,P]=results;
  try{const r=await fetch('data/performance-drivers.json');if(r.ok)D=await r.json();}catch{D=null;}
  if(D?.photos){const keys=['q1_exterior','q1_hottub','q2_room','q2_swing','q3_bedroom','q3_playroom',...D.ladder.map(r=>'rung_'+r.rung),...(D.design_comps||[]).flatMap(c=>['adult','comp'].flatMap(side=>c.rooms.map(r=>`${c.prefix}_${side}_${r}`))),...(D.amenity_scores||[]).map(a=>a.photo)].filter(k=>D.photos[k]);
    const label=k=>{const c=(D.design_comps||[]).find(c=>k.startsWith(c.prefix+'_'));return c?`${k.includes('_adult_')?`Themed · ${c.adult} (${usd(c.adult_revenue)})`:`Conventional comp · ${c.comp} (${usd(c.comp_revenue)})`} · ${D.photos[k].label}`:D.photos[k].label;};
    P.profiles.drivers={title:'What drives performance',photos:keys.map((k,i)=>({...D.photos[k],key:k,index:i+1,label:label(k)}))};}rows=Object.values(E.properties).filter(p=>p.classification===CONF);
  for(const p of Object.values(E.properties)){
    if(!P.profiles[p.id])P.profiles[p.id]={title:p.name,photos:p.adult_reference.photos,rooms:{}};
    for(const c of p.comps)if(!P.profiles[c.comp_id])P.profiles[c.comp_id]={title:c.comp_title,photos:c.review.photos,rooms:{}};
  }
  for(const c of E.candidates)if(num(c.revenue_potential))REV[c.id]=c.revenue_potential;
  for(const p of Object.values(E.properties)){REV[p.id]=p.adult_revenue;for(const c of p.comps)if(num(c.comp_revenue))REV[c.comp_id]=c.comp_revenue;}
  for(const [id,pr] of Object.entries(P.profiles))if(num(REV[id])&&!pr.title.includes('$'))pr.title=`${pr.title} · ${usd(REV[id])}`;
  render();bind();renderProperties();renderMarkets();renderExplorer();
  $('#report').setAttribute('aria-busy','false');document.documentElement.dataset.ready='true';
  if(chapters.some(([id])=>id===location.hash.slice(1)))go(location.hash.slice(1));
  const observer=new IntersectionObserver(entries=>{if(presenting)return;const entry=entries.filter(e=>e.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(entry)updateChapter(entry.target.id);},{rootMargin:'-20% 0px -45% 0px',threshold:[0,.1,.3]});
  $$('[data-chapter]').forEach(el=>observer.observe(el));
}

function render(){
  const s=E.summary,featured=E.featured_ids.map(id=>E.properties[id]);
  $('#chapter-nav').innerHTML=chapters.filter(([id])=>NAV.includes(id)).map(([id,label])=>`<a class="chapter-link" href="#${id}" data-chapter-link="${id}">${label}</a>`).join('');
  const options=chapters.map(([id,label])=>`<option value="${id}">${label}</option>`).join('');$('#present-select').innerHTML=options;$('#mobile-chapters').innerHTML=options;
  const opening=`<section class="chapter" id="question" data-chapter><div class="chapter-inner"><span class="eyebrow">THE CABIN PROOF / 15 CONFIRMED PROPERTIES</span><p class="research-update-date">Confirmed-property comparisons reviewed October 26, 2026</p><div class="findings-opening"><div><h2 class="cover-title">Fifteen confirmed cabins.<br><em>The same +50% premium.</em></h2><p class="findings-deck">The identified properties show higher Revenue Potential than selected conventional cabins with competitive interiors. The advantage varies sharply by property and market.</p><a class="button primary" href="#revenue" data-chapter-link="revenue">See the properties ↓</a></div><div class="finding-main-number"><span class="overline">MEDIAN OBSERVED REVENUE POTENTIAL GAP · n=${s.properties}</span><b>${pct(s.median_premium)}</b><p>Adult property versus its selected conventional comp median. Selected sets contain ${s.comp_min}–${s.comp_max} conventional properties.</p></div></div><div class="finding-metrics"><div><b>${dollars(s.median_dollar)}</b><span>Median Revenue Potential difference</span></div><div><b>${s.above_median} / ${s.properties}</b><span>Above their selected conventional median</span></div><div><b>${s.negative_count}</b><span>Below the selected median · bedroom alternatives</span></div></div><div class="finding-conclusions"><article><span>01</span><p><strong>Pricing power is the recurring signal.</strong> Median ADR gap is ${pct(s.median_adr_premium)}. Occupancy difference is ${pp(s.median_occupancy_pp)}; ${s.both_adr_occupancy}/15 have both higher ADR and occupancy.</p></article><article><span>02</span><p><strong>Premium conventional cabins are competitive.</strong> Strip Lounge (${usd(revOf('1403088011323129843'))}) is ${pct(E.properties['1403088011323129843'].selected_pct_premium)} above five spa-equipped conventional comps.</p></article><article><span>03</span><p><strong>Blue Ridge warrants attention.</strong> Its four-property median is ${pct(E.markets.find(m=>m.market==='Blue Ridge, GA').median_premium)}. Shared controls and functional layouts limit independence.</p></article></div><div class="simple-caution">Revenue Potential is the performance metric. The study covers ${s.study_markets} active vacation markets and ${fmt(s.master_unique)} cleaned listings, with ${s.properties} confirmed examples in ${s.treatment_markets} markets. The identified sample is selected; these observed gaps do not establish a causal theme effect.</div></div></section>`;
  const featuredHTML=`<div class="focused-card-grid">${featured.map(r=>`<article class="focused-card" data-featured="${r.id}"><span class="overline">${esc(r.market)} · ${r.selected_comp_count} COMPS</span><h4>${esc(r.name)}</h4>${fitBadge(r)}<b class="focused-premium ${r.selected_pct_premium<0?'negative':''}">${pct(r.selected_pct_premium)}</b><p>${usd(r.adult_revenue)} adult Revenue Potential<br>${usd(r.selected_comp_median)} conventional median</p><p class="case-fit-note"><strong>${esc(r.comparability.role)}.</strong> ${esc(r.comparability.selection_reason)}</p>${btn(r.id,'Compare rooms & evidence ↗')}</article>`).join('')}</div>`;
  const revenue=inner('revenue','THE PROPERTY COMPARISONS','What earns more.<br>What it comes with.',`<p class="chapter-intro">Nine cases to judge the opportunity: seven core comparisons chosen for documented comp fit, plus both negative Sevierville layout counterexamples. Strong means closer relative fit; Limited means material differences remain; Unresolved means the benchmark needs qualification. Every set is small. The headline still covers all 15 confirmed properties.</p>${featuredHTML}<details class="optional-detail"><summary>Compare all ${s.properties} confirmed properties</summary><div class="control-strip"><label>Market <select id="properties-market"><option value="all">All confirmed markets</option>${E.markets.filter(m=>m.properties).map(m=>`<option>${esc(m.market)}</option>`).join('')}</select></label><label>Sort <select id="revenue-sort"><option value="premium">Percentage gap</option><option value="dollar">Dollar difference</option><option value="revenue">Revenue Potential</option><option value="market">Market</option></select></label></div><p id="property-result-count" class="chart-note"></p><div id="revenue-chart" class="property-card-grid"></div></details><p class="chart-note">All selected conventional properties come from the cleaned source markets. Two confirmed properties use explicitly flagged source-bedroom alternatives. Optional reviewed alternatives are visible in profiles and excluded from the selected median.</p>`,true);
  const strip=E.properties['1403088011323129843'],velvet=E.properties['1376888340135621101'];
  const amenity=inner('amenities','PRICE, NOT NIGHTS','The premium comes from rate.<br>The setting still matters.',`<p class="chapter-intro">Hot tubs, saunas, spa bathrooms, architecture and privacy can make a conventional cabin a strong competitor. Comparing against these alternatives is central to interpreting the revenue gap.</p><div class="two-col">${[velvet,strip].map(r=>`<article class="case-transition"><span class="case-label">${esc(r.market)} · n=${r.selected_comp_count}</span><h3>${esc(r.name)}</h3><div class="winner-number">${pct(r.selected_pct_premium)}</div><p>Adult Revenue Potential ${usd(r.adult_revenue)} versus a ${usd(r.selected_comp_median)} selected conventional median.</p><p>${r.id===velvet.id?'The selected set includes other well-presented A-frames with hot tubs and saunas. The gap remains large, but conventional sleeping capacity, bathrooms, views and shared controls complicate attribution.':'The selected set includes premium conventional spa cabins with hot tubs, saunas and substantial bathrooms. The remaining gap is modest compared with the stronger Blue Ridge observations.'}</p>${btn(r.id,'Compare the interiors ↗')}</article>`).join('')}</div><div class="adjustment-headlines"><div class="adjustment-stat"><b>${pct(s.median_adr_premium)}</b><span>Median ADR gap · 15 properties</span></div><div class="adjustment-stat"><b>${pp(s.median_occupancy_pp)}</b><span>Median occupancy difference · 15 properties</span></div><div class="adjustment-stat"><b>${pct(s.median_p75_gap)}</b><span>Median gap versus selected conventional P75 · 15 properties</span></div></div><div class="simple-caution">Higher ADR is consistent across all 15 confirmed observations; higher occupancy is not. P75 is interpolated from tiny selected sets and is an exploratory benchmark. Physical quality, usable area, views, privacy and precise location remain incompletely matched. A remaining gap is an association, not an isolated theme effect.</div>`);
  const markets=inner('markets','WHERE IT WORKS','Blue Ridge stands out.<br>Sevierville is mixed.',`<p class="chapter-intro">Compare property-level gaps with their sample sizes. Single-property markets are observations, not conclusive market rankings.</p>${marketShortlist()}<details class="optional-detail"><summary>Compare all six confirmed-example markets</summary><div id="market-chart" class="market-bars"></div></details><p class="chart-note">n = confirmed adult properties. Conventional comps are reused; market observations are not independent.</p><div class="control-strip"><label>Explore a market <select id="market-select">${E.markets.map(m=>`<option ${m.market===activeMarket?'selected':''}>${esc(m.market)}</option>`).join('')}</select></label></div><div id="market-details" class="market-details"></div>`,true);
  const implications=inner('implications','LIMITS & NEXT STEPS','A promising concept.<br>A property-specific opportunity.',`<div class="meaning-list"><article><h3>Where the evidence is strongest</h3><p>Velvet Chains (${usd(revOf('1376888340135621101'))}) and Tangled Up (${usd(revOf('1452875891719932372'))}) remain strong relative to competitive A-frame alternatives. Red Sunset (${usd(revOf('1104485212592092496'))}) supplies a distinct positive Broken Bow observation. Strip Lounge (${usd(revOf('1403088011323129843'))}) is much closer to the premium conventional benchmark.</p></article><article><h3>What limits the conclusion</h3><p>There are ${s.unique_controls} unique selected conventional properties for the confirmed sample. Controls are shared, sets contain only ${s.comp_min}–${s.comp_max} comps, and both negative Sevierville properties describe one sleeping bedroom plus adult space, despite two source bedrooms. Usable-area parity remains unresolved. A Broken Bow adult listing explicitly advertises a studio-style layout. These findings remain in the study and the layout sensitivity.</p></article></div>${acquisitionBuybox()}<div class="simple-next-step"><span class="overline">THE ACQUISITION SCREEN</span><p>The most useful next step is to test a specific acquisition candidate against premium conventional cabins: compare measured usable area, sleeping-room layout, bathrooms, micro-location and privacy. Pigeon Forge and Gatlinburg each have three selected comps; Banner Elk remains a single-comp observation. Revenue Potential stays the agreed performance metric.</p></div>${reliabilitySummary()}<details class="optional-detail"><summary>How sensitive are the findings?</summary><div class="table-scroll"><table class="data-table"><thead><tr><th>Comparison</th><th>Properties</th><th>Median gap</th></tr></thead><tbody>${E.sensitivity.map(s=>`<tr><td>${esc(s.test)}</td><td>${s.properties}</td><td>${pct(s.median_premium)}</td></tr>`).join('')}</tbody></table></div><p class="chart-note">Restrictions change the available sample. These are descriptive checks, not independent causal tests.</p></details><details class="optional-detail"><summary>Cabin versus urban: what the expanded set shows</summary><p>The 56-listing expansion adds urban and exploratory listings, and it has been reconciled with this study at the level of findings. Themed hot-tub cabins in getaway markets carry the premium. City houses, apartments and suites have medians of $37–49K, and themed listings without a hot tub only match their own comps. The two datasets use different AirDNA pulls, so their figures are reported separately and never pooled; both show a median gap of about +50% against reviewed conventional comps.</p></details><p class="closing-thesis">Worth investigating.<br><span class="accent">Comp quality determines what the signal means.</span></p>`);
  const explorer=inner('explorer','OPTIONAL DETAIL','All candidates.<br>Including the uncertain ones.',`<details class="optional-detail" id="candidate-explorer"><summary>Browse all ${E.candidates.length} reviewed candidates</summary><div class="explorer-controls"><label>Search <input id="explorer-search" type="search" placeholder="Listing, market or Airbnb ID"></label><label>Classification <select id="explorer-class"><option value="all">All classifications</option>${[...new Set(E.candidates.map(c=>c.classification))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>Market <select id="explorer-market"><option value="all">All markets</option>${E.markets.map(m=>`<option>${esc(m.market)}</option>`).join('')}</select></label></div><p id="explorer-count" class="chart-note" aria-live="polite"></p><div class="table-scroll"><table class="data-table"><thead><tr><th>Listing / market</th><th>Classification</th><th>Revenue Potential</th><th>BR / sleeps</th><th>Selected gap</th></tr></thead><tbody id="explorer-rows"></tbody></table></div></details>`,true);
  const sources=inner('sources','RESEARCH FILES','The decision summary.',`<p class="chapter-intro">One set of findings, with the property evidence and comp records available for inspection.</p><div class="download-list"><a class="download-link" href="downloads/DECISION_SUMMARY.md" download><span>Decision summary<small>Findings and implications</small></span><span>↓</span></a><a class="download-link" href="downloads/STR_SEARCH_RESEARCH.xlsx" download><span>Research workbook<small>Property results, selected comps, markets and methodology</small></span><span>↓</span></a></div><details class="optional-detail"><summary>Definitions and interpretation</summary>${Object.entries(E.methodology).map(([k,x])=>`<p><strong>${esc(k.replaceAll('_',' '))}.</strong> ${esc(x)}</p>`).join('')}</details><div class="research-footer"><span>STR SEARCH / OCTOBER 2026</span><span>Revenue Potential comparisons · selected sample · property-specific evidence</span></div>`);
  $('#report').innerHTML=answerChapter()+driversChapter()+opening+revenue+amenity+markets+implications+explorer+sources;
}

const fig=(key,cls='',caption=true)=>{const p=D?.photos?.[key];if(!p)return '';const n=P.profiles.drivers?.photos.find(x=>x.key===key)?.index;return `<figure class="driver-photo ${cls}"><button class="photo-zoom" data-photo-open="drivers:${n}" aria-label="Enlarge photo: ${esc(p.label)}"><img src="${esc(p.path)}" alt="${esc(p.label)}" loading="lazy"></button>${caption?`<figcaption>${esc(p.label)}</figcaption>`:''}</figure>`;};
const figs=keys=>`<div class="answer-photos">${keys.map(k=>fig(k)).join('')}</div>`;
function designComps(){
  if(!D?.design_comps)return '';
  return `<div class="design-comps" id="design-comps"><span class="overline">DESIGN COMPS · TOP-EARNING THEMED CABINS VS. THEIR BEST CONVENTIONAL COMP</span><h3>Comparable interiors, different results.</h3><p class="chart-note">The three top-earning themed cabins with full comp sets, each beside the highest-earning of its own photo-reviewed conventional comps (selected for comparable finishes, style and hot tubs, not on revenue). Every reviewed comp for these cabins earns less. These are the strongest cases, not typical results: across all listings with comps the median gap is +50%, and 10 of 41 earn less than their comps.</p>
  ${D.design_comps.map(c=>`<article class="design-pair"><header><h4>${esc(c.style)} · ${esc(c.market)}</h4><b class="${c.gap_vs_comp<0?'negative':''}">${pct(c.gap_vs_comp)} vs. this comp</b></header><div class="design-sides"><div><span class="side-label adult">THEMED · ${esc(c.adult)} · ${usd(c.adult_revenue)}</span><div class="design-photos">${c.rooms.map(r=>fig(c.prefix+'_adult_'+r)).join('')}</div></div><div><span class="side-label">CONVENTIONAL · ${esc(c.comp)} · ${usd(c.comp_revenue)}</span><div class="design-photos">${c.rooms.map(r=>fig(c.prefix+'_comp_'+r)).join('')}</div></div></div><p class="chart-note">${esc(c.note)} Comp median ${usd(c.comp_median)}; ${pct(c.gap)} vs. the median.</p></article>`).join('')}</div>`;
}

function amenityScores(){
  if(!D?.amenity_scores)return '';
  const k=v=>num(v)?'$'+fmt(v/1000)+'K':'—',whole=v=>fmt(v*100)+'%';
  const card=a=>`<article class="amenity-card" data-amenity="${esc(a.key)}">${fig(a.photo)}<div class="amenity-body"><div class="amenity-head"><h4>${esc(a.name)}</h4><span class="verdict verdict-${esc(a.verdict.toLowerCase().replace(' ','-'))}">${esc(a.verdict)}</span></div>
    ${num(a.score)?`<div class="score-row"><div class="score-track"><i style="width:${a.score}%"></i></div><b>${a.score}</b></div>`:`<div class="score-row unscored"><span>${a.key==='led_or_red_lighting'?'Not scored: nearly every listing has it':'Not scored: only '+a.cabins_with+' comparable cabins have one'}</span></div>`}
    <dl class="amenity-stats"><div><dt>$100K+ listings</dt><dd>${whole(a.top)}</dd></div><div><dt>Under $50K</dt><dd>${whole(a.lower)}</dd></div>
    <div class="wide"><dt>Comparable cabins</dt><dd>${a.cabins_with>=4&&a.cabins_without>=4?`${k(a.median_with)} with (${a.cabins_with}) vs. ${k(a.median_without)} without (${a.cabins_without}) · <strong class="${a.lift<0?'negative':''}">${pct(a.lift)}</strong>`:`All listings: ${k(a.all_median_with)} with (${a.all_with}) vs. ${k(a.all_median_without)} without (${a.all_without})`}</dd></div></dl>
    <p>${esc(a.note)}</p></div></article>`;
  return `<div class="amenity-scores" id="amenity-scores"><span class="overline">KINK AMENITIES, SCORED · 54 LIVE LISTINGS</span><h3>What each piece is worth.</h3>
  <p class="chart-note">Score (0–100) = 50 + half the gap between how often $100K+ and under-$50K listings have the item (percentage points) + half the revenue difference among comparable themed hot-tub cabins in getaway markets (median with vs. without, %). Scored only when at least four comparable cabins have the item and four do not. The verdict also weighs how common the item is among top earners. Photos are actual listings; each caption shows that listing's modeled revenue. Associations on small samples, not proof that an item causes revenue.</p>
  <div class="amenity-grid">${D.amenity_scores.map(card).join('')}</div>
  <p class="chart-note">Too few listings to judge: ${D.amenity_too_few.map(x=>`${esc(x.name)} (${x.listings})`).join(', ')}.</p></div>`;
}

function answerChapter(){
  if(!D)return '';
  const A=D.answer,s=E.summary,h=D.headline,k=v=>'$'+fmt(v/1000)+'K',QP=[['q1_exterior','q1_hottub'],['q2_room','q2_swing'],['q3_bedroom','q3_playroom']];
  return `<section class="chapter findings-cover answer-cover" id="answer" data-chapter><div class="chapter-inner"><span class="eyebrow">STR SEARCH / RED ROOM RESEARCH / OCTOBER 2026</span><p class="research-update-date">Research updated October 27, 2026</p>
  <p class="answer-question"><span>THE QUESTION</span>Do adult-themed Airbnbs earn more than comparable conventional properties, and what drives it?</p>
  <div class="answer-head"><div><h1>${esc(A.title)}<br><em>${esc(A.title_em)}</em></h1><p class="findings-deck">${esc(A.deck)}</p></div>
  <div class="answer-proof"><div><b>${pct(s.median_premium)}</b><span>${s.properties} confirmed cabins vs. photo-matched conventional cabins · ${s.above_median} of ${s.properties} above</span></div><div><b>${pct(h.median_gap)}</b><span>${h.with_comps} of ${h.listings} listings in 40 cities with reviewed comps · ${h.above} above, ${h.below} below</span></div></div></div>
  <div class="answer-questions" id="answer-questions">${A.questions.map((x,i)=>`<article><span class="overline">QUESTION ${i+1}</span><h3>${esc(x.q)}</h3><p class="answer-short">${esc(x.a)}</p>${figs(QP[i])}<ul>${x.points.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${i===1?'<a class="mini-link answer-more" href="#amenity-scores">See each amenity scored, with photos ↓</a>':''}</article>`).join('')}</div>
  <div class="answer-bottom"><div><span class="overline">THE REVENUE LADDER · MEDIAN MODELED REVENUE</span><ol class="answer-ladder" id="answer-ladder">${D.ladder.map(r=>`<li>${fig('rung_'+r.rung,'ladder-thumb')}${D.photos['rung_'+r.rung]?.listing_url?`<a class="ladder-link" href="${esc(D.photos['rung_'+r.rung].listing_url)}" target="_blank" rel="noopener noreferrer">View on Airbnb ↗</a>`:''}<b>${k(r.median_revenue)}</b><span>${r.rung==='Top'?'Top':'Rung '+esc(r.rung)}</span><small>${esc({'0':'No hot tub','1':'Hot tub, city unit','2':'+ cabin in a getaway market','3':'+ real kit & decent finishes','Top':'+ operator & pricing'}[r.rung])}</small></li>`).join('')}</ol></div>
  <div class="answer-buy"><span class="overline">WHAT TO BUY</span><ul>${A.buy.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div></div>
  <p class="answer-confidence"><strong>Confidence:</strong> ${esc(A.confidence)} <a class="mini-link" href="#drivers" data-chapter-link="drivers">See the evidence ↓</a></p></div></section>`;
}

function driversChapter(){
  if(!D)return '';
  const h=D.headline,max=Math.max(...D.ladder.map(r=>r.p75));
  const k=v=>num(v)?'$'+fmt(v/1000)+'K':'—';
  const whole=v=>num(v)?fmt(v*100)+'%':'—';
  const rung=r=>{const top=r.rung==='Top';
    return `<div class="ladder-rung" data-rung="${esc(r.rung)}"><div class="rung-id">Rung<b>${esc(r.rung)}</b></div><div><h4>${esc(r.label)}</h4><small>${esc(D.rung_examples[r.rung]||'')}</small></div><div class="rung-bar"><div class="rung-track"><i class="rung-range" style="left:${r.p25/max*100}%;width:${(r.p75-r.p25)/max*100}%"></i><i class="rung-fill ${top?'top':''}" style="width:${r.median_revenue/max*100}%"></i></div><div class="rung-meta">${r.listings} listings · ADR ${usd(r.median_adr)} · occupancy ${whole(r.median_occupancy)} · ${whole(r.share_100k)} at $100K+${num(r.median_gap)?` · ${pct(r.median_gap)} vs. comps`:''}</div></div><div class="rung-value">${k(r.median_revenue)}<small>median${top?' · range '+esc(r.range_text):''}</small></div></div>`;};
  const list=items=>`<ul class="driver-list">${items.map(([t,b])=>`<li><strong>${esc(t)}</strong>${esc(b)}</li>`).join('')}</ul>`;
  const eq=`<div class="table-scroll"><table class="data-table" id="driver-equipment"><thead><tr><th>Photographed item</th><th>All listings</th><th>Top tier ($100K+)</th><th>Lower tier (&lt;$50K)</th></tr></thead><tbody>${D.equipment.map(e=>`<tr><td>${esc(e.item)}</td><td><i class="share-bar" style="width:${e.all*60}px"></i>${pct(e.all,false)}</td><td>${pct(e.top,false)}</td><td>${pct(e.lower,false)}</td></tr>`).join('')}</tbody></table></div>`;
  const bands=`<div class="kit-bands">${D.kit_bands.map(([l,v])=>`<div><span>${esc(l)}</span><b class="${v<0?'negative':''}">${pct(v)}</b><span>vs. comps</span></div>`).join('')}</div>`;
  return inner('drivers','WHY SOME EARN MORE / 56 LISTINGS','The revenue ladder.<br><em>Why some red rooms earn more.</em>',
    `<p class="research-update-date">Added October 27, 2026 · ${esc(D.metadata.revenue_label)}</p><p class="chapter-intro">${esc(D.metadata.sample)}</p>
    <div class="driver-headline" id="driver-headline"><div><b>${pct(h.median_gap)}</b><span>Median modeled-revenue gap vs. photo-reviewed conventional comps (${h.with_comps} listings with comps)</span></div><div><b>${h.above} / ${h.below}</b><span>Listings above / below their reviewed comps</span></div><div><b>${pct(h.broad_median_uplift)}</b><span>The same listings vs. every same-bedroom listing in their city — why broad comparisons overstate the premium</span></div></div>
    <p class="chart-note">Each live listing sits on the highest rung it qualifies for. Bars show median modeled revenue; the lighter band marks the middle half of listings (full range for the top rung).</p>
    <div class="ladder" id="revenue-ladder">${D.ladder.map(rung).join('')}</div>
    <div class="driver-steps">${D.steps.map(([t,b],i)=>`<article><span class="overline">STEP ${i+1}</span><h4>${esc(t)}</h4><p>${esc(b)}</p></article>`).join('')}</div>
    ${designComps()}<h3 class="driver-detail-title">The evidence behind the answers</h3><div class="driver-grid"><div><span class="overline">QUESTION 1</span><h3>Which traditional features are needed?</h3>${list(D.traditional)}</div>
    <div><span class="overline">QUESTION 2</span><h3>Which kink amenities matter?</h3><ul class="driver-list">${D.kink_points.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${bands}</div></div>
    ${amenityScores()}<details class="optional-detail"><summary>What the photos show: equipment by revenue tier</summary>${eq}</details>
    <div class="driver-grid"><div><span class="overline">QUESTION 3</span><h3>Other patterns linked to stronger performance</h3>${list(D.patterns.slice(0,3))}</div><div><span class="overline">&nbsp;</span><h3>&nbsp;</h3>${list(D.patterns.slice(3))}</div></div>
    <ul class="driver-caveats">${D.caveats.map(c=>`<li>${esc(c)}</li>`).join('')}</ul>`,true);
}

function renderProperties(){
  const selected=rows.filter(p=>market==='all'||p.market===market).sort((a,b)=>sort==='market'?a.market.localeCompare(b.market)||b.selected_pct_premium-a.selected_pct_premium:sort==='dollar'?b.selected_dollar_premium-a.selected_dollar_premium:sort==='revenue'?b.adult_revenue-a.adult_revenue:b.selected_pct_premium-a.selected_pct_premium);
  const max=Math.max(...rows.map(p=>Math.max(p.adult_revenue,p.selected_comp_median)));
  $('#property-result-count').textContent=`${selected.length} confirmed properties / selected conventional comparisons / USD`;
  $('#revenue-chart').innerHTML=selected.map(p=>`<article class="property-card" data-property-card="${p.id}"><div class="property-card-heading"><div><button class="property-name" data-open="${p.id}">${esc(p.name)}</button><p>${esc(p.market)} / ${p.bedrooms} source BR / sleeps ${p.sleep_capacity}</p></div><span class="property-premium ${p.selected_pct_premium<0?'negative':''}">${pct(p.selected_pct_premium)}</span></div><div class="property-card-amenities"><span class="overline">ADULT PROPERTY AMENITIES</span>${badges(p.amenities)}</div><button class="revenue-row" data-open="${p.id}" aria-label="Inspect ${esc(p.name)} and its selected comps"><span class="revenue-label"><strong>${usd(p.adult_revenue)}</strong><small>vs ${usd(p.selected_comp_median,2)} selected median</small></span><span class="revenue-plot" aria-hidden="true"><i class="bar adult" style="width:${p.adult_revenue/max*100}%"></i><i class="bar conventional" style="width:${p.selected_comp_median/max*100}%"></i></span></button><p class="selected-card-note ${p.selected_pct_premium<0?'negative':''}">${p.layout_alternatives?'Bedroom-layout alternatives; source bedrooms differ.':p.selected_comp_count<3?'Very thin set; descriptive only.':p.confidence+'.'}</p><div class="property-card-footer"><span>${p.selected_comp_count} selected comps</span>${btn(p.id,'Inspect the comps ↗')}</div></article>`).join('');
}

function renderMarkets(){
  const selected=E.markets.filter(m=>m.properties).sort((a,b)=>b.median_premium-a.median_premium),max=Math.max(...selected.map(m=>Math.abs(m.median_premium)));
  $('#market-chart').innerHTML=selected.map(m=>`<button class="market-row ${m.median_premium<0?'negative':''}" data-market="${esc(m.market)}"><span class="market-name">${esc(m.market)}</span><span class="market-track"><i class="market-fill" style="width:${Math.max(1,Math.abs(m.median_premium)/max*100)}%"></i></span><span class="market-premium">${pct(m.median_premium)}</span><span class="market-n">n=${m.properties}</span></button>`).join('');
  $('#market-select').value=activeMarket;
  const m=E.markets.find(m=>m.market===activeMarket),properties=rows.filter(p=>p.market===activeMarket);
  $('#market-details').innerHTML=`<h3>${esc(activeMarket)}</h3>`+(properties.length?`<p class="chart-note">${m.single_property?'Single-property observation.':'Selected sample; controls may be reused.'} ${m.unique_controls} unique conventional controls.</p><div class="property-mini-list">${properties.map(p=>`<button class="property-mini" data-open="${p.id}"><span><strong>${esc(p.name)}</strong><small>${usd(p.adult_revenue)} / ${usd(p.selected_comp_median,2)} selected median</small><small>ADR ${pct(p.selected_adr_pct_premium)} · occupancy ${pp(p.selected_occupancy_difference_pp)}</small></span><span><b>${pct(p.selected_pct_premium)}</b><small>${p.selected_comp_count} comps</small></span></button>`).join('')}</div>`:'<div class="market-empty">No verified examples in this study. This does not establish that the concept fails in this market.</div>');
}

function renderExplorer(){
  const q=explorer.query.toLowerCase().trim(),filtered=E.candidates.filter(c=>(explorer.classification==='all'||c.classification===explorer.classification)&&(explorer.market==='all'||c.market===explorer.market)&&(!q||[c.id,c.title,c.market].some(x=>String(x||'').toLowerCase().includes(q))));
  $('#explorer-count').textContent=`${filtered.length} of ${E.candidates.length} candidates`;
  $('#explorer-rows').innerHTML=filtered.map(c=>`<tr><td>${btn(c.id,esc(c.title))}<small>${esc(c.market)} · ${c.id}</small></td><td>${esc(c.classification)}</td><td>${usd(c.revenue_potential)}</td><td>${fmt(c.bedrooms)} / ${fmt(c.sleep_capacity)}</td><td>${E.properties[c.id]?pct(E.properties[c.id].selected_pct_premium):'Outside confirmed/probable comparison'}</td></tr>`).join('')||'<tr><td colspan="5">No candidate matches this search.</td></tr>';
}

function openProfile(id){
  const p=E.properties[id],candidate=E.candidates.find(c=>c.id===id);if(!candidate)return;
  profile={id,tab:'overview',comp:p?.default_comp_id,room:'all'};
  $('#profile-content').innerHTML=`<div class="profile-top"><span class="overline">STR SEARCH / PROPERTY RESEARCH</span><button class="icon-button" data-close-profile aria-label="Close property">×</button></div><div class="profile-body"><div class="profile-heading"><div><span class="tag">${esc(candidate.classification)}</span><h2 id="profile-title">${esc(p?.name||candidate.title)}</h2><p class="profile-revenue"><strong>${usd(revOf(id))}</strong> modeled revenue (Revenue Potential, last 12 months)</p><p>${esc(candidate.market)} · ${fmt(candidate.bedrooms)} source bedrooms · sleeps ${fmt(candidate.sleep_capacity)}</p></div><a class="button" href="${esc(candidate.airbnb_url)}" target="_blank" rel="noopener noreferrer">Open Airbnb ↗</a></div><div class="profile-tabs" role="tablist" aria-label="Property research">${[['overview','Listing'],['comps','Compare comps'],['evidence','Evidence']].map(([key,label])=>`<button id="profile-tab-${key}" class="profile-tab" role="tab" data-tab="${key}" aria-controls="profile-panel">${label}</button>`).join('')}</div><div id="profile-panel" role="tabpanel"></div></div>`;
  renderProfile();if(!$('#property-dialog').open)$('#property-dialog').showModal();document.body.classList.add('dialog-open');
}
function renderProfile(){
  const p=E.properties[profile.id],candidate=E.candidates.find(c=>c.id===profile.id),panel=$('#profile-panel');
  $$('.profile-tab').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.tab===profile.tab));b.tabIndex=b.dataset.tab===profile.tab?0:-1;});panel.setAttribute('aria-labelledby','profile-tab-'+profile.tab);
  if(profile.tab==='evidence'||!p){panel.innerHTML=`<span class="overline">CLASSIFICATION EVIDENCE</span><p class="listing-theme-note">${esc(p?.theme_evidence||candidate.evidence_summary)}</p><p class="chart-note">Reviewed ${esc(candidate.verification_date)}. Classification describes advertised features.</p><div class="adult-amenity-panel"><span class="overline">RECORDED AMENITIES</span>${badges(candidate.amenities)}</div>${p?.interior_review?`<p><strong>Latest interior review (${esc(p.interior_review_date)}):</strong> ${esc(p.interior_review)}</p><p><a href="${esc(p.adult_url)}" target="_blank" rel="noopener noreferrer">Public listing / layout evidence ↗</a></p>`:''}<p class="chart-note">Cleaned source: ${esc(candidate.source_workbook)} · ${esc(candidate.source_worksheet)} · row ${fmt(candidate.source_row_number)}.</p>${!p?'<p>This candidate is outside the confirmed/probable numerical comparison.</p>':''}`;return;}
  if(profile.tab==='overview'){
    panel.innerHTML=`<div class="profile-metrics"><div><b>${usd(p.adult_revenue)}</b><span>ADULT REVENUE POTENTIAL</span></div><div><b>${usd(p.selected_comp_median,2)}</b><span>SELECTED CONVENTIONAL MEDIAN</span></div><div><b>${pct(p.selected_pct_premium)}</b><span>${dollars(p.selected_dollar_premium)} DIFFERENCE</span></div></div>${fitPanel(p)}${reliabilityLine(p)}<p class="selected-caution">${p.selected_comp_count} selected comps. ${esc(p.confidence)}. ${esc(p.comparability_note)}</p><div class="adult-amenity-panel"><span class="overline">ADULT PROPERTY AMENITIES</span>${badges(p.amenities)}</div>${p.interior_review?`<div class="adult-amenity-panel"><span class="overline">INTERIOR &amp; LAYOUT FINDING · ${esc(p.interior_review_date)}</span><p>${esc(p.interior_review)}</p>${p.layout_review?`<p><strong>Functional layout:</strong> ${esc(p.layout_review)}</p>`:''}</div>`:''}<p class="listing-theme-note"><strong>Advertised theme:</strong> ${esc(p.theme_evidence)}</p><div class="simple-property-findings"><p><strong>ADR:</strong> ${usd(p.adult_adr,2)} versus ${usd(p.selected_comp_adr,2)} (${pct(p.selected_adr_pct_premium)}).</p><p><strong>Occupancy:</strong> ${pct(p.adult_occupancy,false)} versus ${pct(p.selected_comp_occupancy,false)} (${pp(p.selected_occupancy_difference_pp)}).</p></div><button class="button primary" data-tab="comps">Compare interiors & selected comps ↗</button><details class="optional-detail"><summary>Individual comp revenues and sensitivity</summary><div class="selected-values">${p.comps.filter(c=>c.status==='selected').map(c=>`<p><a href="${esc(c.comp_url)}" target="_blank" rel="noopener noreferrer">${esc(c.comp_title)}</a> — ${usd(c.comp_revenue)}</p>`).join('')}</div><p>${p.leave_one_comp_out_min===null?'Only one comp: a leave-one-out comparison is unavailable.':`Leaving out one selected comp at a time gives gaps of ${pct(p.leave_one_comp_out_min)} to ${pct(p.leave_one_comp_out_max)}. This is not a confidence interval.`}</p></details>`;return;
  }
  const chosen=p.comps.find(c=>c.comp_id===profile.comp)||p.comps[0],selected=p.comps.filter(c=>c.status==='selected'),audited=Object.keys(P.profiles[p.id]?.rooms||{}).length>0;
  const pair=roomGallery({id:p.id,review:p.adult_reference,label:'ADULT REFERENCE',title:`${p.name} · ${usd(p.adult_revenue)}`,url:p.adult_url,P,room:profile.room,esc})+roomGallery({id:chosen.comp_id,review:chosen.review,label:'CONVENTIONAL COMP',title:`${chosen.comp_title} · ${usd(chosen.comp_revenue)}`,url:chosen.comp_url,P,room:profile.room,esc});
  const matrix=audited?roomMatrix({r:p,P,room:profile.room,chosenId:chosen.comp_id,esc}):'';
  panel.innerHTML=`<div class="selected-metrics"><div><b>${pct(p.selected_pct_premium)}</b><span>Observed gap · ${p.selected_comp_count} selected comps</span></div><div><b>${usd(p.selected_comp_median,2)}</b><span>Selected conventional median</span></div><div><b>${dollars(p.selected_dollar_premium)}</b><span>Revenue Potential difference</span></div></div>${fitPanel(p)}${reliabilityLine(p)}<p class="selected-caution">${esc(p.comparability_note)}</p><div class="adult-amenity-panel"><span class="overline">ADULT PROPERTY AMENITIES</span>${badges(p.amenities)}</div><div class="visual-controls"><label>Inspect a property<select id="selected-comp-select">${p.comps.map(c=>`<option value="${c.comp_id}" ${c.comp_id===chosen.comp_id?'selected':''}>${c.status==='optional'?'Optional alternative: ':''}${esc(c.comp_title)} — ${usd(c.comp_revenue)}</option>`).join('')}</select></label></div><p class="focused-pair-note"><strong>${chosen.status==='selected'?'Selected comp':'Optional alternative; excluded from the median'}.</strong> ${esc(chosen.fit_note)}</p>${audited?roomToolbar({room:profile.room,adultId:p.id,P,esc}):''}<div class="visual-comparison">${pair}</div><p class="chart-note">${chosen.use_count>1?`This conventional property appears in ${chosen.use_count} selected adult-property comp sets; pairings are not independent. `:''}${chosen.distance_km!==null?'Approximate source distance: '+fmt(chosen.distance_km,1)+' km. ':''}Comp advertised area: ${chosen.advertised_area_sqft?fmt(chosen.advertised_area_sqft)+' sq ft (unverified public claim)':'Unavailable'}. Unknown area is not assumed equal.</p>${matrix}<div class="table-scroll"><table class="data-table focused-comp-table"><thead><tr><th>Selected conventional property</th><th>Source BR / guests / beds / baths</th><th>Revenue Potential</th><th>ADR</th><th>Occupancy</th><th>Hot tub / sauna advertising</th></tr><tr class="adult-benchmark-row"><td>${esc(p.name)}</td><td>${p.bedrooms} / ${p.sleep_capacity} / ${p.beds} / ${p.bathrooms}</td><td>${usd(p.adult_revenue)}</td><td>${usd(p.adult_adr,2)}</td><td>${pct(p.adult_occupancy,false)}</td><td>See recorded amenities above</td></tr></thead><tbody>${selected.map(c=>`<tr data-selected-comp="${c.comp_id}"><td><a href="${esc(c.comp_url)}" target="_blank" rel="noopener noreferrer">${esc(c.comp_title)} ↗</a><small>${c.comp_id}</small>${c.layout_alternative?'<span class="layout-tag">Bedroom-layout alternative</span>':''}${c.functional_layout_reference?'<span class="layout-tag">Functional open-layout reference</span>':''}</td><td>${c.comp_bedrooms} / ${c.comp_sleeps} / ${c.comp_beds} / ${c.comp_bathrooms}</td><td>${usd(c.comp_revenue)}</td><td>${usd(c.comp_adr,2)}</td><td>${pct(c.comp_occupancy,false)}</td><td>${['hot_tub','sauna'].map(k=>c.public_amenities[k]==='advertised'?'Advertised':c.public_amenities[k]==='explicitly_absent'?'Explicitly absent':'Unverified').join(' / ')}</td></tr>`).join('')}</tbody></table></div><button class="button" data-export-comps>Export selected comps ↓</button><p class="chart-note">Changing the inspected image or optional alternative does not change the selected benchmark. Source zero flags are not independently verified absence. All comparisons use existing cleaned-source Revenue Potential.</p>`;
}

function showPhoto(id,index){const list=P.profiles[id];if(!list)return;viewer={id,position:Math.max(0,list.photos.findIndex(p=>p.index===Number(index)))};renderPhoto();if(!$('#photo-lightbox').open)$('#photo-lightbox').showModal();}
function renderPhoto(){const list=P.profiles[viewer.id],p=list.photos[viewer.position],name=p.label||list.title+' / '+(roomNames[p.room]||'Listing photo');$('#photo-lightbox-title').textContent=name;$('#photo-lightbox-image').src=p.path;$('#photo-lightbox-image').alt=name;$('#photo-lightbox-counter').textContent=`${viewer.position+1} of ${list.photos.length} reviewed photos`;$('#photo-lightbox-source').href=p.listing_url||(/^[0-9]+$/.test(viewer.id)?'https://www.airbnb.com/rooms/'+viewer.id:p.source_url);$('#photo-lightbox-source').textContent='View this listing on Airbnb ↗';$('.photo-lightbox-note').textContent=viewer.id==='drivers'?'Actual listing photos from several properties. Use ← / → to browse these photos; Escape closes the viewer.':'Actual reviewed listing photo. Use ← / → to browse this property; Escape closes the viewer.';}
function stepPhoto(n){viewer.position=(viewer.position+n+P.profiles[viewer.id].photos.length)%P.profiles[viewer.id].photos.length;renderPhoto();}
function exportComps(){const p=E.properties[profile.id],keys=['comp_id','comp_title','comp_url','market','comp_bedrooms','comp_sleeps','comp_revenue','comp_adr','comp_occupancy','fit_note'];const cell=v=>'"'+String(v??'').replaceAll('"','""')+'"';const csv=[keys.join(','),...p.comps.filter(c=>c.status==='selected').map(c=>keys.map(k=>cell(c[k])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`selected_comps_${p.id}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function updateChapter(id){chapter=id;$$('[data-chapter-link]').forEach(a=>a.classList.toggle('active',a.dataset.chapterLink===id));$('#present-select').value=id;$('#mobile-chapters').value=id;$('#present-counter').textContent=`${chapters.findIndex(c=>c[0]===id)+1} / ${chapters.length}`;if(presenting)$$('[data-chapter]').forEach(s=>s.classList.toggle('present-active',s.id===id));}
function go(id){if(!chapters.some(c=>c[0]===id))return;updateChapter(id);$('#'+id).scrollIntoView({behavior:'instant',block:'start'});}
function togglePresentation(on=!presenting){presenting=on;document.body.classList.toggle('presenting',on);$('#presentation-controls').hidden=!on;$('#presentation-toggle').setAttribute('aria-pressed',String(on));if(!on)$$('.present-active').forEach(x=>x.classList.remove('present-active'));go(chapter);}
function advance(n){const i=chapters.findIndex(c=>c[0]===chapter);go(chapters[Math.max(0,Math.min(chapters.length-1,i+n))][0]);}
function bind(){
  $('#properties-market').onchange=e=>{market=e.target.value;renderProperties();};$('#revenue-sort').onchange=e=>{sort=e.target.value;renderProperties();};
  $('#market-select').onchange=e=>{activeMarket=e.target.value;renderMarkets();};
  $('#explorer-search').oninput=e=>{explorer.query=e.target.value;renderExplorer();};$('#explorer-class').onchange=e=>{explorer.classification=e.target.value;renderExplorer();};$('#explorer-market').onchange=e=>{explorer.market=e.target.value;renderExplorer();};
  $('#presentation-toggle').onclick=()=>togglePresentation();$('#present-exit').onclick=()=>togglePresentation(false);$('#present-next').onclick=()=>advance(1);$('#present-prev').onclick=()=>advance(-1);$('#present-select').onchange=e=>go(e.target.value);$('#mobile-chapters').onchange=e=>go(e.target.value);
  $('#property-dialog').addEventListener('close',()=>document.body.classList.remove('dialog-open'));
  document.addEventListener('click',e=>{
    const photo=e.target.closest('[data-photo-open]');if(photo){showPhoto(...photo.dataset.photoOpen.split(':'));return;}
    if(e.target.closest('[data-close-photo]')){$('#photo-lightbox').close();return;}
    const step=e.target.closest('[data-photo-step]');if(step){stepPhoto(Number(step.dataset.photoStep));return;}
    const open=e.target.closest('[data-open]');if(open){openProfile(open.dataset.open);return;}
    const tab=e.target.closest('[data-tab]');if(tab){profile.tab=tab.dataset.tab;renderProfile();return;}
    const room=e.target.closest('[data-photo-room]');if(room){profile.room=room.dataset.photoRoom;renderProfile();$('.photo-room-toolbar')?.scrollIntoView({block:'start',behavior:'instant'});return;}
    const inspect=e.target.closest('[data-inspect-focused]');if(inspect){profile.comp=inspect.dataset.inspectFocused;renderProfile();$('.visual-controls')?.scrollIntoView({block:'start',behavior:'instant'});return;}
    if(e.target.closest('[data-close-profile]')){$('#property-dialog').close();return;}
    if(e.target.closest('[data-export-comps]')){exportComps();return;}
    const m=e.target.closest('[data-market]');if(m){activeMarket=m.dataset.market;renderMarkets();return;}
    const link=e.target.closest('[data-chapter-link]');if(link){e.preventDefault();go(link.dataset.chapterLink);}
  });
  document.addEventListener('change',e=>{if(e.target.id==='selected-comp-select'){profile.comp=e.target.value;renderProfile();}});
  document.addEventListener('keydown',e=>{
    if($('#photo-lightbox').open){if(e.key==='Escape'){e.preventDefault();$('#photo-lightbox').close();}if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();stepPhoto(e.key==='ArrowRight'?1:-1);}return;}
    if(e.target.matches('.profile-tab')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=['overview','comps','evidence'],i=tabs.indexOf(profile.tab);profile.tab=e.key==='Home'?tabs[0]:e.key==='End'?tabs[2]:tabs[(i+(e.key==='ArrowRight'?1:2))%3];renderProfile();$('#profile-tab-'+profile.tab).focus();return;}
    if($('#property-dialog').open)return;
    if(presenting&&e.key==='Escape'){togglePresentation(false);return;}
    if(presenting&&!e.target.closest('input,select,textarea')){if(e.key==='ArrowRight'||e.key==='PageDown'){e.preventDefault();advance(1);}if(e.key==='ArrowLeft'||e.key==='PageUp'){e.preventDefault();advance(-1);}}
  });
}
init().catch(error=>{console.error(error);$('#report').innerHTML=`<div class="error-message"><h1>Research could not be opened.</h1><p>${esc(error.message)}</p></div>`;document.documentElement.dataset.ready='error';});
